"""Independent R33 judgments from rendered UI; no candidate implementation inspection."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'rounds/r33/reports'
C={f['id']:f for f in json.loads((ROOT/'contract/user-features.json').read_text())['features']}
D={'round':'R33','evaluator':'/root/review_r31_r34','platforms':{},'feature_observations':{},'journey_observations':{},'findings':[]}

def ep(p,folder,*names):
    return [f'evidence/{p}/{folder}/{n}.json' for n in names]
def obs(fid,p,evidence,reason,verified=(),partial=(),missing=(),status='partial'):
    assertions={}
    for state,keys in [('verified',verified),('partial',partial),('missing',missing)]:
        for key in keys:
            kind,n=key.split(':'); assert int(n)<len(C[fid]['mustKeep'][kind]),(fid,key)
            assertions[key]={'status':state,'observation':reason}
    D['feature_observations'].setdefault(fid,{})[p]={'status':status,'reason':reason,'evidence':evidence,'assertions':assertions}
def journey(jid,p,evidence,reason,status='partial'):
    D['journey_observations'].setdefault(jid,{})[p]={'status':status,'reason':reason,'evidence':evidence}

